class NumberedCanvas(canvas.Canvas):
    def __init__(self, *args, **kwargs):
        canvas.Canvas.__init__(self, *args, **kwargs)
        self._saved_page_states = []
    def showPage(self):
        self._saved_page_states.append(dict(self.__dict__))
        self._startPage()
    def save(self):
        total = len(self._saved_page_states)
        for state in self._saved_page_states:
            self.__dict__.update(state)
            if self._pageNumber > 1:
                self.setFont("Helvetica", 8)
                self.setFillColor(MUTED)
                self.drawRightString(PAGE_W - 20*mm, 12*mm, f"{self._pageNumber}  |  {total}")
            canvas.Canvas.showPage(self)
        canvas.Canvas.save(self)

class ReportDoc(BaseDocTemplate):
    def __init__(self, filename):
        super().__init__(filename, pagesize=A4, leftMargin=20*mm, rightMargin=20*mm, topMargin=21*mm, bottomMargin=20*mm, title="EcoSort AI - Full Project Report", author="Arshpreet Singh, Sarbjit Singh, Pooja")
        cover = Frame(20*mm, 20*mm, PAGE_W-40*mm, PAGE_H-40*mm, id="cover", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
        body = Frame(20*mm, 19*mm, PAGE_W-40*mm, PAGE_H-40*mm, id="body", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
        self.addPageTemplates([
            PageTemplate(id="Cover", frames=cover, onPage=self.cover_page),
            PageTemplate(id="Body", frames=body, onPage=self.body_page),
        ])
    def cover_page(self, c, doc):
        c.saveState()
        c.setFillColor(DEEP); c.rect(0, PAGE_H-13*mm, PAGE_W, 13*mm, fill=1, stroke=0)
        c.setFillColor(LIME); c.rect(0, PAGE_H-13*mm, 7*mm, 13*mm, fill=1, stroke=0)
        c.restoreState()
    def body_page(self, c, doc):
        c.saveState()
        c.setStrokeColor(LINE); c.setLineWidth(.6)
        c.line(20*mm, PAGE_H-14*mm, PAGE_W-20*mm, PAGE_H-14*mm)
        c.setFont("Helvetica-Bold", 8); c.setFillColor(GREEN)
        c.drawString(20*mm, PAGE_H-11*mm, "ECOSORT AI  /  PROJECT REPORT")
        c.setFont("Helvetica", 8); c.setFillColor(MUTED)
        c.drawRightString(PAGE_W-20*mm, PAGE_H-11*mm, "Garbage Classification with Deep Learning")
        c.line(20*mm, 16*mm, PAGE_W-20*mm, 16*mm)
        c.restoreState()
    def afterFlowable(self, flowable):
        if isinstance(flowable, ChapterTitle):
            key = f"chapter-{flowable.number}"
            self.canv.bookmarkPage(key)
            self.canv.addOutlineEntry(flowable.text, key, 0, False)
            self.notify("TOCEntry", (0, flowable.text, self.page, key))

class ChapterTitle(Paragraph):
    def __init__(self, number, text):
        self.number = number
        self.text = f"{number:02d}  |  {text}"
        super().__init__(self.text, styles["ChapterEco"])

class SectionTitle(Paragraph):
    def __init__(self, text):
        self.text = text
        super().__init__(text, styles["SectionEco"])

class FlowDiagram(Flowable):
    def __init__(self, labels, width=170*mm, height=27*mm):
        super().__init__(); self.labels=labels; self.width=width; self.height=height
    def draw(self):
        gap=3*mm; n=len(self.labels); bw=(self.width-gap*(n-1))/n; y=5*mm; bh=17*mm
        for i,label in enumerate(self.labels):
            x=i*(bw+gap)
            self.canv.setFillColor([PALE, HexColor("#E5F3F6"), HexColor("#FCEBE6"), PALE][i%4])
            self.canv.setStrokeColor(LINE); self.canv.roundRect(x,y,bw,bh,2*mm,fill=1,stroke=1)
            self.canv.setFillColor(DEEP); self.canv.setFont("Helvetica-Bold",7.4)
            lines=label.split("\n")
            for j,line in enumerate(lines): self.canv.drawCentredString(x+bw/2,y+bh/2+(len(lines)-1)*4-j*9-2,line)
            if i<n-1:
                self.canv.setStrokeColor(TEAL); self.canv.setLineWidth(1.2)
                self.canv.line(x+bw+0.5*mm,y+bh/2,x+bw+gap-0.5*mm,y+bh/2)

