def make_table(data, widths, header=True, font=8.3):
    converted=[]
    for row in data:
        converted.append([Paragraph(str(v), ParagraphStyle("cell", fontName="Helvetica-Bold" if header and len(converted)==0 else "Helvetica", fontSize=font, leading=font+2, textColor=colors.white if header and len(converted)==0 else INK)) for v in row])
    t=Table(converted, colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
    commands=[("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5),("GRID",(0,0),(-1,-1),.35,LINE)]
    if header: commands += [("BACKGROUND",(0,0),(-1,0),GREEN),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,PALE])]
    else: commands += [("ROWBACKGROUNDS",(0,0),(-1,-1),[colors.white,PALE])]
    t.setStyle(TableStyle(commands)); return t
