story += [PageBreak(), chapter(39,"Appendices"), sec("Appendix A  Team contribution plan"), make_table([["Team member","Proposed responsibility area","Example deliverables"],["Arshpreet Singh","Dataset and model development","Dataset review; MobileNetV2 training; class weighting; validation analysis."],["Sarbjit Singh","Backend and integration","Flask routes; model loading; upload and camera API integration; deployment configuration."],["Pooja","Interface, testing, and documentation","Responsive UI; capture-review workflow; interface checks; report and presentation."],["All team members","Shared project work","Planning; integration review; demonstration preparation; final submission review."]],[34*mm,54*mm,63*mm],font=7.8), p("The project files do not contain a contribution log. These responsibilities are proposed from the codebase work areas and should be confirmed by the team before submission.","SmallEco"), sec("Appendix B  Repository map"), make_table([["Path","Purpose"],["app.py","Flask routes, image decoding, model loading, and inference."],["garbage_classification_model.ipynb","Notebook for data loading, model training, and evaluation."],["garbage_classification/","Folder-based labeled image dataset."],["models/metadata.json","Class names, image dimensions, class counts, class weights, and saved validation metrics."],["models/*.keras","Saved trained Keras model artifacts."],["models/training_history.png","Training and validation accuracy/loss plot."],["templates/index.html","Upload, camera, capture/review controls, and prediction-result UI."],["static/styles.css","Responsive styles and branded interface presentation."],["static/manifest.webmanifest","PWA name, start URL, display mode, theme, and icon metadata."],["static/service-worker.js","Application shell caching and GET request cache behavior."],["requirements.txt","Python dependency constraints."],["render.yaml, runtime.txt, .python-version","Hosted service settings and Python runtime pin."]],[51*mm,100*mm]), sec("Appendix C  Reproducible setup and remaining submission details"), p("1. Install Python 3.11 and create a project virtual environment.<br/>2. Install dependencies from requirements.txt.<br/>3. Confirm models/metadata.json and at least one .keras model are present.<br/>4. Run python app.py and open http://127.0.0.1:5000.<br/>5. For hosted camera access, use HTTPS and verify the browser camera permission flow.<br/>6. Before submission, record the tested environment, model filename, test images, observed outputs, and any deployment errors.<br/>7. Complete the programme, branch, roll numbers, academic session, and submission date; confirm contribution roles, verify dataset provenance, and obtain institutional approval.","BodyLeftEco"), PageBreak(), sec("Appendix D  Technical terminology"), make_table([["Term","Meaning in this project"],["Augmentation","Random image transformations applied during model training to vary examples."],["Backbone","The pretrained MobileNetV2 feature-extraction network."],["Class weight","A training-loss multiplier derived from class frequency."],["Fine-tuning","Updating selected pretrained layers at a low learning rate for the target task."],["Inference","Using the saved model to calculate scores for a new input image."],["PWA","Progressive Web App metadata and shell behavior for an installable web experience."],["Softmax score","A normalized model output across the configured classes; not automatically calibrated confidence."],["Validation set","Data used during development to monitor and select a model; distinct from an independent test set."],["WSGI","Python server interface used by Gunicorn to host the Flask application."]],[42*mm,109*mm]), sec("Appendix E  Recommended independent evaluation protocol"), p("1. Define the intended user, target device types, capture conditions, and inclusion/exclusion rules.<br/>2. Set aside a test set before model selection; avoid near-duplicate leakage from training images.<br/>3. Record consent/provenance and labels, then have ambiguous examples reviewed against a written class guide.<br/>4. Report sample counts and class-wise precision, recall, F1, support, confusion matrix, and aggregate metrics.<br/>5. Stratify results by lighting, background, viewpoint, object condition, device, and single-item versus mixed scenes.<br/>6. Measure end-to-end request time and failure rate on the target hosting configuration separately from model accuracy.<br/>7. Publish failure examples and known limitations; do not use the test set for repeated tuning.","BodyLeftEco"), PageBreak(), sec("Appendix F  College submission checklist"), *bullet_list(["Confirm degree/programme, department, semester, academic session, roll numbers, and approved project title.","Verify all student names and spellings on cover, declaration, certificate, presentation, and forms.","Confirm the proposed contribution roles with each team member.","Ask the mentor/HOD and co-mentor to review and sign institutional pages as required.","Verify dataset source, license, and permission before redistribution.","Replace preview-only screenshots with live app screenshots if the department requires runtime evidence.","Run and document the recommended software, camera, mobile layout, and deployment tests.","Attach the final repository commit or archive and make sure report metrics match the saved model metadata."]), p("This report is a technical project document prepared from the supplied repository snapshot. Institutional format, declarations, signatures, and approval remain subject to the department's requirements.","SmallEco")]

